  130: // --------------------------------------------------------------------------- process identity
  131: 
  132: /// The process's start time as a UTC round-trip string ([`crate::liveness::proc::process_start_iso`])
  133: /// with the plugin's TEST HOOK (test mode only) `CODEX_CONSULT_TEST_START_UNREADABLE=<pid>[,<pid>]`:
  134: /// those pids, while they exist, read as `""` (a start time that cannot be read).
  135: fn start_iso_hooked(pid: u32) -> Option<String> {
  136:     let iso = crate::liveness::proc::process_start_iso(pid)?;
  137:     if let Some(list) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_START_UNREADABLE") {
  138:         if list.split(',').any(|p| p.trim() == pid.to_string()) {
  139:             return Some(String::new());
  140:         }
  141:     }
  142:     Some(iso)
  143: }
  144: 
  145: /// A UTC round-trip time as .NET ticks (100 ns since 0001-01-01 UTC); `None` when it does not parse.
  146: fn iso_ticks(iso: &str) -> Option<i64> {
  147:     let t = iso.trim();
  148:     if t.is_empty() {
  149:         return None;
  150:     }
  151:     let d = DateTime::parse_from_rfc3339(t).ok()?.with_timezone(&Utc);
  152:     Some(
  153:         d.timestamp() * TICKS_PER_SECOND
  154:             + i64::from(d.timestamp_subsec_nanos()) / 100
  155:             + DOTNET_UNIX_EPOCH_TICKS,
  156:     )
  157: }
  158: 
  159: /// `Get-ProcessStartTicks`: a process's start time in ticks (UTC, 100 ns - the full resolution
  160: /// Windows reports): `None` - no such process; `Some(-1)` - it exists but its start time cannot be
  161: /// read; else the ticks.
  162: pub fn process_start_ticks(pid: u32) -> Option<i64> {
  163:     if pid == 0 {
  164:         return None;
  165:     }
  166:     let iso = start_iso_hooked(pid)?;
  167:     Some(iso_ticks(&iso).unwrap_or(-1))
  168: }
  169: 
  170: /// The identity of a pid against the start ticks recorded for it (`Get-PidIdentityTicks`).
  171: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
  172: pub enum Identity {
  173:     /// A process with this pid runs with exactly those ticks (outside Windows: within a second).
  174:     Alive,
  175:     /// No such process, or one with another start (the pid was handed to another process).
  176:     Gone,
  177:     /// No ticks were recorded, or the start time cannot be read now - never removed on a guess.
  178:     Unknown,
  179: }
  180: 
  181: /// `Get-PidIdentityTicks`.
  182: pub fn pid_identity_ticks(pid: u32, ticks: i64) -> Identity {
  183:     if pid == 0 {
  184:         return Identity::Gone;
  185:     }
  186:     let Some(live) = process_start_ticks(pid) else {
  187:         return Identity::Gone;
  188:     };
  189:     if ticks <= 0 || live < 0 {
  190:         return Identity::Unknown;
  191:     }
  192:     if live == ticks {
  193:         return Identity::Alive;
  194:     }
  195:     if !cfg!(windows) && (live - ticks).abs() < TICKS_PER_SECOND {
  196:         return Identity::Alive;
  197:     }
  198:     Identity::Gone
  199: }
  200: 
  201: /// This process's start ticks, read once; 0 when they cannot be read (its file then names no
  202: /// start: its identity counts as unknown, never folded).
  203: pub fn own_start_ticks() -> i64 {
  204:     static OWN: OnceLock<i64> = OnceLock::new();
  205:     *OWN.get_or_init(|| match process_start_ticks(std::process::id()) {
  206:         Some(t) if t > 0 => t,
  207:         _ => 0,
  208:     })
  209: }
  210: 
  211: /// `Test-PidAlive` with the start-unreadable hook: a process with this pid exists and - when a
  212: /// start time was recorded and one can be read now - has that start time.
  213: fn pid_alive_hooked(pid: u32, start_time: &str) -> bool {
  214:     if pid == 0 {
  215:         return false;
  216:     }
  217:     let Some(live) = start_iso_hooked(pid) else {
  218:         return false;
  219:     };
  220:     if !start_time.is_empty()
  221:         && !live.is_empty()
  222:         && !crate::liveness::proc::same_start_time(&live, start_time)
  223:     {
  224:         return false;
  225:     }
  226:     true
  227: }
