  302: /// One not-spooled file (`Get-TelemetryNotSpooledFiles`).
  303: #[derive(Debug, Clone)]
  304: pub(crate) struct NsFile {
  305:     pub path: PathBuf,
  306:     pub name: String,
  307:     /// The producer's pid (0: a legacy or a staged file).
  308:     pub pid: u32,
  309:     /// The producer's start ticks (a staged file: its staging ticks).
  310:     pub ticks: i64,
  311:     /// A legacy single file (the plugin's or C3's wave-2 name).
