  316: 
  317: /// The not-spooled files of `dir`: the producers' files, the legacy single files and their staged
  318: /// generations, sorted by name (case-insensitively). Another name that starts the same way is not
  319: /// one of them.
  320: pub(crate) fn list_files(dir: &Path) -> Vec<NsFile> {
  321:     let mut out = Vec::new();
  322:     let Ok(rd) = fs::read_dir(dir) else {
  323:         return out;
  324:     };
  325:     for e in rd.flatten() {
  326:         if !e.file_type().map(|t| t.is_file()).unwrap_or(false) {
  327:             continue;
  328:         }
  329:         let Some(name) = e.file_name().to_str().map(str::to_string) else {
  330:             continue;
  331:         };
  332:         let lower = name.to_ascii_lowercase();
  333:         let path = e.path();
  334:         if lower == LEGACY_FILE || lower == C3_LEGACY_FILE {
  335:             out.push(NsFile {
  336:                 path,
  337:                 name,
  338:                 pid: 0,
  339:                 ticks: 0,
  340:                 legacy: true,
  341:                 staged: false,
  342:             });
  343:             continue;
  344:         }
  345:         let Some(rest) = lower
  346:             .strip_prefix(NS_PREFIX)
  347:             .and_then(|r| r.strip_suffix(".ndjson"))
  348:         else {
  349:             continue;
  350:         };
  351:         let digits = |s: &str, max: usize| {
  352:             !s.is_empty() && s.len() <= max && s.bytes().all(|b| b.is_ascii_digit())
  353:         };
  354:         if let Some(t) = rest.strip_prefix("legacy-") {
  355:             if digits(t, 19) {
  356:                 if let Ok(ticks) = t.parse::<i64>() {
  357:                     out.push(NsFile {
  358:                         path,
  359:                         name,
  360:                         pid: 0,
  361:                         ticks,
  362:                         legacy: false,
  363:                         staged: true,
  364:                     });
  365:                 }
  366:             }
  367:             continue;
  368:         }
  369:         let Some((p, t)) = rest.split_once('-') else {
  370:             continue;
  371:         };
  372:         if !digits(p, 10) || !digits(t, 19) {
  373:             continue;
  374:         }
  375:         let (Ok(pid), Ok(ticks)) = (p.parse::<u64>(), t.parse::<i64>()) else {
  376:             continue;
  377:         };
  378:         if pid > i32::MAX as u64 {
  379:             continue;
  380:         }
  381:         out.push(NsFile {
  382:             path,
  383:             name,
  384:             pid: pid as u32,
  385:             ticks,
  386:             legacy: false,
  387:             staged: false,
  388:         });
  389:     }
  390:     out.sort_by_key(|f| f.name.to_ascii_lowercase());
  391:     out
  392: }
