  394: /// `Add-TelemetryNotSpooled`: one `{time, why}` line appended to THIS process's own file - no lock
  395: /// (no other process appends to it; the retry, up to 1 s, only covers a reader of this very file).
  396: /// `Err(why)` when the line could not be written.
  397: pub fn append(paths: &LocalPaths, why: &str) -> Result<(), String> {
  398:     let line = format!(
  399:         "{}\n",
  400:         json!({ "time": now_iso(), "why": c3_core::one_line(why) })
  401:     );
  402:     let own = paths.own_file();
  403:     let mut err = String::new();
  404:     for _ in 0..20 {
  405:         let r = fs::create_dir_all(&paths.ns_dir)
  406:             .and_then(|_| OpenOptions::new().create(true).append(true).open(&own))
  407:             .and_then(|mut f| f.write_all(line.as_bytes()));
  408:         match r {
  409:             Ok(()) => return Ok(()),
  410:             Err(e) => {
  411:                 err = c3_core::one_line(&e.to_string());
  412:                 thread::sleep(Duration::from_millis(50));
  413:             }
  414:         }
  415:     }
  416:     Err(format!(
  417:         "the not-spooled count {} could not be written ({err})",
  418:         own.display()
  419:     ))
  420: }
