  540: /// The events not spooled since the last flush (`Get-TelemetryNotSpooled`).
  541: #[derive(Debug, Clone, Default, PartialEq, Eq)]
  542: pub struct NsCount {
  543:     /// Since the last flush: every complete line less the record's `not_spooled_seen`.
  544:     pub count: u64,
  545:     /// The latest `why` by time (`""` when none since the last flush).
  546:     pub last: String,
  547:     /// Its `time` as written.
  548:     pub when: String,
  549:     /// Every complete line of every file counted.
  550:     pub total: u64,
  551:     /// The files counted.
  552:     pub files: u64,
  553:     /// The legacy files' complete lines (part of `total`).
  554:     pub legacy_lines: u64,
  555: }
  556: 
  557: /// `Get-TelemetryNotSpooled`: the complete lines of every not-spooled file, summed, less the last
  558: /// flush's `not_spooled_seen` (`all`: every line counts). A file the record's `not_spooled_folded[]`
  559: /// names counts only its complete lines BEYOND the recorded bytes (those are in a fold's note
  560: /// already); one shorter than that is another file and counts whole; a bare name counts nothing. A
  561: /// legacy file counts whole, always (a fold stages it before counting it).
  562: pub fn count(paths: &LocalPaths, all: bool) -> NsCount {
  563:     let mut r = NsCount::default();
  564:     let files = list_files(&paths.ns_dir);
  565:     if files.is_empty() {
  566:         return r;
  567:     }
  568:     let last = read_last(&paths.last);
  569:     let folded = folded_map(last.as_ref());
  570:     let seen = if all {
  571:         0
  572:     } else {
  573:         count_value(last.as_ref().and_then(|l| l.get("not_spooled_seen"))).unwrap_or(0)
  574:     };
  575:     // (time, why, when) of the latest line
  576:     let mut latest: Option<(Option<DateTime<chrono::FixedOffset>>, String, String)> = None;
  577:     for f in &files {
  578:         let mut text = None;
  579:         if !f.legacy {
  580:             if let Some(e) = folded.get(&f.name.to_ascii_lowercase()) {
  581:                 if e.bytes < 0 {
  582:                     continue;
  583:                 }
  584:                 text = read_shared_from(&f.path, e.bytes as u64);
  585:             }
  586:         }
  587:         let named = text.is_some();
  588:         let text = match text.or_else(|| read_shared(&f.path)) {
  589:             Some(t) => t,
  590:             None => continue,
  591:         };
  592:         let lines = complete_lines(&text, false);
  593:         // a named file with nothing beyond its recorded bytes is accounted for
  594:         if named && lines.is_empty() {
  595:             continue;
  596:         }
  597:         r.files += 1;
  598:         r.total += lines.len() as u64;
  599:         if f.legacy {
  600:             r.legacy_lines += lines.len() as u64;
  601:         }
  602:         for l in lines {
  603:             let Ok(o) = serde_json::from_str::<Value>(l) else {
  604:                 continue;
  605:             };
  606:             let when_text = value_text(o.get("time"));
  607:             let at = DateTime::parse_from_rfc3339(when_text.trim()).ok();
  608:             let newer = match &latest {
  609:                 None => true,
  610:                 Some((prev, _, _)) => at.is_some() && (prev.is_none() || at >= *prev),
  611:             };
  612:             if newer {
  613:                 latest = Some((at, value_text(o.get("why")), when_text));
  614:             }
  615:         }
  616:     }
  617:     r.count = (r.total as i64 - seen).max(0) as u64;
  618:     if r.count > 0 {
  619:         if let Some((_, why, when)) = latest {
  620:             r.last = why;
  621:             r.when = when;
  622:         }
  623:     }
  624:     r
  625: }
