  628: 
  629: /// A fold in progress (`Merge-TelemetryNotSpooled`): the files it counted are held open until
  630: /// [`Fold::complete`].
  631: #[derive(Debug, Default)]
  632: pub(crate) struct Fold {
  633:     /// The lines folded now.
  634:     pub lines: u64,
  635:     /// The files folded now ("gone producers").
  636:     pub producers: u64,
  637:     /// The complete lines of the files kept (live producers) - the record's `not_spooled_seen`.
  638:     pub seen: u64,
  639:     /// Every file this fold covers, `{name, bytes}` - the record's `not_spooled_folded`.
  640:     pub folded: Vec<FoldedEntry>,
  641:     /// Why a legacy file was not staged (one note each).
  642:     pub notes: Vec<String>,
  643:     open: Vec<(PathBuf, File)>,
  644:     ns_dir: PathBuf,
  645: }
  646: 
  647: /// Open a file for the fold: read and write, sharing only delete (an appender waits; the fold can
  648: /// still delete it under this handle).
  649: fn open_exclusive(path: &Path) -> std::io::Result<File> {
  650:     let mut o = OpenOptions::new();
  651:     o.read(true).write(true);
  652:     #[cfg(windows)]
  653:     {
  654:         use std::os::windows::fs::OpenOptionsExt;
  655:         const FILE_SHARE_DELETE: u32 = 0x0000_0004;
  656:         o.share_mode(FILE_SHARE_DELETE);
  657:     }
  658:     o.open(path)
  659: }
  660: 
  661: /// UTC now in .NET ticks.
  662: fn utc_now_ticks() -> i64 {
  663:     let n = Utc::now();
  664:     n.timestamp() * TICKS_PER_SECOND
  665:         + i64::from(n.timestamp_subsec_nanos()) / 100
  666:         + DOTNET_UNIX_EPOCH_TICKS
  667: }
  668: 
  669: /// (E26) Rename a legacy file to a unique staged name before it is counted; `Err(note)` when a
  670: /// writer kept it (retried about 1 s) - not folded this flush.
  671: fn stage_legacy(dir: &Path, legacy: &Path) -> Result<(), String> {
  672:     let mut ticks = utc_now_ticks();
  673:     while dir.join(format!("{STAGED_PREFIX}{ticks}.ndjson")).exists() {
  674:         ticks += 1;
  675:     }
  676:     let staged = dir.join(format!("{STAGED_PREFIX}{ticks}.ndjson"));
  677:     let mut err = String::new();
  678:     for _ in 0..10 {
  679:         match fs::rename(legacy, &staged) {
  680:             Ok(()) => return Ok(()),
  681:             Err(e) => {
  682:                 err = c3_core::one_line(&e.to_string());
  683:                 thread::sleep(Duration::from_millis(100));
  684:             }
  685:         }
  686:     }
  687:     if legacy.exists() {
  688:         return Err(format!(
  689:             "the legacy not-spooled file {} could not be staged ({err}) - not folded this flush",
  690:             legacy.display()
  691:         ));
  692:     }
  693:     Ok(())
  694: }
  695: 
  696: /// `Merge-TelemetryNotSpooled`, under the spool lock: every file whose producer is gone (no process
  697: /// with its pid and start ticks), every staged legacy generation and every file `already` names is
  698: /// opened exclusively and counted (a gone producer's last line without a line end too); a producer
  699: /// that lives - or whose identity cannot be confirmed - keeps its file (its complete lines: `seen`).
  700: /// The legacy files are staged first (E26). NOTHING is deleted here (E20): the caller saves the
  701: /// record, then [`Fold::complete`] deletes. A file `already` names (E24) of the same length or
  702: /// longer is not counted again - only its complete lines beyond the recorded bytes are new; a
  703: /// shorter one is another file, folded afresh; a bare name is held for its delete, uncounted.
  704: pub(crate) fn merge(paths: &LocalPaths, already: &HashMap<String, FoldedEntry>) -> Fold {
  705:     let mut r = Fold {
  706:         ns_dir: paths.ns_dir.clone(),
  707:         ..Fold::default()
  708:     };
  709:     for f in list_files(&paths.ns_dir).iter().filter(|f| f.legacy) {
  710:         if let Err(note) = stage_legacy(&paths.ns_dir, &f.path) {
  711:             r.notes.push(note);
  712:         }
  713:     }
  714:     for f in list_files(&paths.ns_dir) {
  715:         // (E26) a legacy file is never counted (nor seen) under its own name: staged above, or busy
  716:         if f.legacy {
  717:             continue;
  718:         }
  719:         let rec = already.get(&f.name.to_ascii_lowercase()).map(|e| e.bytes);
  720:         let gone =
  721:             rec.is_some() || f.staged || pid_identity_ticks(f.pid, f.ticks) == Identity::Gone;
  722:         if gone {
  723:             if let Ok(mut fs_) = open_exclusive(&f.path) {
  724:                 let mut earlier = false;
  725:                 let counted: Option<(u64, i64)> = (|| {
  726:                     let len = fs_.metadata().ok()?.len() as i64;
  727:                     let n;
  728:                     if rec.is_some_and(|b| b < 0 || len >= b) {
  729:                         earlier = true;
  730:                         let b = rec.unwrap_or(-1);
  731:                         n = if b >= 0 && len > b {
  732:                             fs_.seek(SeekFrom::Start(b as u64)).ok()?;
  733:                             let mut buf = Vec::new();
  734:                             fs_.read_to_end(&mut buf).ok()?;
  735:                             complete_lines(&String::from_utf8_lossy(&buf), false).len() as u64
  736:                         } else {
  737:                             0
  738:                         };
  739:                     } else {
  740:                         let mut buf = Vec::new();
  741:                         fs_.read_to_end(&mut buf).ok()?;
