  647: /// Open a file for the fold: read and write, sharing only delete (an appender waits; the fold can
  648: /// still delete it under this handle).
  649: fn open_exclusive(path: &Path) -> std::io::Result<File> {
  650:     let mut o = OpenOptions::new();
  651:     o.read(true).write(true);
  652:     #[cfg(windows)]
  653:     {
  654:         use std::os::windows::fs::OpenOptionsExt;
  655:         const FILE_SHARE_DELETE: u32 = 0x0000_0004;
  656:         o.share_mode(FILE_SHARE_DELETE);
  657:     }
  658:     o.open(path)
  659: }
