  661: /// UTC now in .NET ticks.
  662: fn utc_now_ticks() -> i64 {
  663:     let n = Utc::now();
  664:     n.timestamp() * TICKS_PER_SECOND
  665:         + i64::from(n.timestamp_subsec_nanos()) / 100
  666:         + DOTNET_UNIX_EPOCH_TICKS
  667: }
