  669: /// (E26) Rename a legacy file to a unique staged name before it is counted; `Err(note)` when a
  670: /// writer kept it (retried about 1 s) - not folded this flush.
  671: fn stage_legacy(dir: &Path, legacy: &Path) -> Result<(), String> {
  672:     let mut ticks = utc_now_ticks();
  673:     while dir.join(format!("{STAGED_PREFIX}{ticks}.ndjson")).exists() {
  674:         ticks += 1;
  675:     }
  676:     let staged = dir.join(format!("{STAGED_PREFIX}{ticks}.ndjson"));
  677:     let mut err = String::new();
  678:     for _ in 0..10 {
  679:         match fs::rename(legacy, &staged) {
  680:             Ok(()) => return Ok(()),
  681:             Err(e) => {
  682:                 err = c3_core::one_line(&e.to_string());
  683:                 thread::sleep(Duration::from_millis(100));
  684:             }
  685:         }
  686:     }
  687:     if legacy.exists() {
  688:         return Err(format!(
  689:             "the legacy not-spooled file {} could not be staged ({err}) - not folded this flush",
  690:             legacy.display()
  691:         ));
  692:     }
  693:     Ok(())
  694: }
