  696: /// `Merge-TelemetryNotSpooled`, under the spool lock: every file whose producer is gone (no process
  697: /// with its pid and start ticks), every staged legacy generation and every file `already` names is
  698: /// opened exclusively and counted (a gone producer's last line without a line end too); a producer
  699: /// that lives - or whose identity cannot be confirmed - keeps its file (its complete lines: `seen`).
  700: /// The legacy files are staged first (E26). NOTHING is deleted here (E20): the caller saves the
  701: /// record, then [`Fold::complete`] deletes. A file `already` names (E24) of the same length or
  702: /// longer is not counted again - only its complete lines beyond the recorded bytes are new; a
  703: /// shorter one is another file, folded afresh; a bare name is held for its delete, uncounted.
  704: pub(crate) fn merge(paths: &LocalPaths, already: &HashMap<String, FoldedEntry>) -> Fold {
  705:     let mut r = Fold {
  706:         ns_dir: paths.ns_dir.clone(),
  707:         ..Fold::default()
  708:     };
  709:     for f in list_files(&paths.ns_dir).iter().filter(|f| f.legacy) {
  710:         if let Err(note) = stage_legacy(&paths.ns_dir, &f.path) {
  711:             r.notes.push(note);
  712:         }
  713:     }
  714:     for f in list_files(&paths.ns_dir) {
  715:         // (E26) a legacy file is never counted (nor seen) under its own name: staged above, or busy
  716:         if f.legacy {
  717:             continue;
  718:         }
  719:         let rec = already.get(&f.name.to_ascii_lowercase()).map(|e| e.bytes);
  720:         let gone =
  721:             rec.is_some() || f.staged || pid_identity_ticks(f.pid, f.ticks) == Identity::Gone;
  722:         if gone {
  723:             if let Ok(mut fs_) = open_exclusive(&f.path) {
  724:                 let mut earlier = false;
  725:                 let counted: Option<(u64, i64)> = (|| {
  726:                     let len = fs_.metadata().ok()?.len() as i64;
  727:                     let n;
  728:                     if rec.is_some_and(|b| b < 0 || len >= b) {
  729:                         earlier = true;
  730:                         let b = rec.unwrap_or(-1);
  731:                         n = if b >= 0 && len > b {
  732:                             fs_.seek(SeekFrom::Start(b as u64)).ok()?;
  733:                             let mut buf = Vec::new();
  734:                             fs_.read_to_end(&mut buf).ok()?;
  735:                             complete_lines(&String::from_utf8_lossy(&buf), false).len() as u64
  736:                         } else {
  737:                             0
  738:                         };
  739:                     } else {
  740:                         let mut buf = Vec::new();
  741:                         fs_.read_to_end(&mut buf).ok()?;
  742:                         n = complete_lines(&String::from_utf8_lossy(&buf), true).len() as u64;
  743:                     }
  744:                     Some((n, len))
  745:                 })();
  746:                 if let Some((n, len)) = counted {
  747:                     r.folded.push(FoldedEntry {
  748:                         name: f.name.clone(),
  749:                         bytes: len,
  750:                     });
  751:                     r.open.push((f.path.clone(), fs_));
  752:                     if !earlier || n > 0 {
  753:                         r.lines += n;
  754:                         r.producers += 1;
  755:                     }
  756:                     continue;
  757:                 }
  758:             }
  759:             if let Some(b) = rec {
  760:                 // named and cannot be opened: it stays named, never counted as kept
  761:                 r.folded.push(FoldedEntry {
  762:                     name: f.name.clone(),
  763:                     bytes: b,
  764:                 });
  765:                 continue;
  766:             }
  767:         }
  768:         if let Some(t) = read_shared(&f.path) {
  769:             r.seen += complete_lines(&t, false).len() as u64;
  770:         }
  771:     }
  772:     r
  773: }
