  777:     /// every file the fold holds (under its handle: nothing appends meanwhile); then every handle is
  778:     /// closed. The entries whose file is still there afterwards (the record goes on naming them).
  779:     pub(crate) fn complete(&mut self, delete: bool) -> Vec<FoldedEntry> {
  780:         for (path, file) in self.open.drain(..) {
  781:             if delete {
  782:                 let _ = fs::remove_file(&path);
  783:             }
  784:             drop(file);
